SELECT sm.sm_ship_mode_id, sm.sm_type, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_return_ship_cost) AS total_ship_cost, AVG(cr.cr_return_quantity) AS avg_return_qty, DENSE_RANK() OVER (ORDER BY SUM(cr.cr_return_amount) DESC) AS ship_mode_rank, CASE WHEN SUM(cr.cr_return_amount) > 500000 THEN 'High' WHEN SUM(cr.cr_return_amount) > 200000 THEN 'Medium' ELSE 'Low' END AS volume_category FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY sm.sm_ship_mode_id, sm.sm_type ORDER BY ship_mode_rank
